import ee, math, sys
ee.Initialize(project='earthsense-436113')

# 1. Geometry & Time Definitions
boston_pt = ee.Geometry.Point([-71.0589, 42.3601])
geom = boston_pt.buffer(5000)  # 5 km around Boston center
start = ee.Date('2019-01-29')
end = ee.Date('2019-02-06')  # exclusive; covers through 2019-02-05

def pick_band(col, candidates):
    size = col.size().getInfo()
    if size == 0:
        return None, None, 0
    try:
        bands = col.first().bandNames().getInfo()
    except Exception:
        return col, None, size
    for b in candidates:
        if b in bands:
            return col, b, size
    return col, None, size

def get_dailycol_and_band():
    # Try ERA5-Land Daily Aggregate
    try:
        col = ee.ImageCollection('ECMWF/ERA5_LAND/DAILY_AGGR').filterDate(start, end)
        col, band, size = pick_band(col, ['temperature_2m_max', 'maximum_2m_air_temperature'])
        if band:
            return col.sort('system:time_start'), band, 'ECMWF/ERA5_LAND/DAILY_AGGR', size
    except Exception:
        pass
    # Try ERA5 Daily
    try:
        col = ee.ImageCollection('ECMWF/ERA5/DAILY').filterDate(start, end)
        col, band, size = pick_band(col, ['maximum_2m_air_temperature', 't2m_max', 'temperature_2m_max'])
        if band:
            return col.sort('system:time_start'), band, 'ECMWF/ERA5/DAILY', size
    except Exception:
        pass
    # Fallback: derive from ERA5-Land Hourly
    try:
        hours = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY').filterDate(start, end).select('temperature_2m')
        if hours.size().getInfo() == 0:
            return None, None, None, 0
        nDays = ee.Date(end).difference(start, 'day').int()
        dates = ee.List.sequence(0, nDays.subtract(1)).map(lambda d: start.advance(ee.Number(d), 'day'))
        def per_day(d):
            d = ee.Date(d)
            im = hours.filterDate(d, d.advance(1,'day')).max().rename('temperature_2m_max')
            return im.set('system:time_start', d.millis())
        dailycol = ee.ImageCollection(dates.map(per_day))
        return dailycol.sort('system:time_start'), 'temperature_2m_max', 'ERA5_LAND_HOURLY->DAILY_MAX', dailycol.size().getInfo()
    except Exception:
        return None, None, None, 0

try:
    col, band, source_id, img_count = get_dailycol_and_band()
    if col is None or band is None:
        print(f"Images: 0 (no usable collection/band)")
        print("C1")
        sys.exit(0)
    print(f"Source: {source_id}, Band: {band}, Images: {img_count}")
    # 3. Processing and stats per day
    def img_to_feat(img):
        val = img.select(band).reduceRegion(
            reducer=ee.Reducer.mean(),
            geometry=geom,
            scale=9000,
            maxPixels=1e9
        ).get(band)
        cnt = img.select(band).reduceRegion(
            reducer=ee.Reducer.count(),
            geometry=geom,
            scale=9000,
            maxPixels=1e9
        ).get(band)
        return ee.Feature(None, {
            'date': ee.Date(img.get('system:time_start')).format('YYYY-MM-dd'),
            'tmaxK': val,
            'count': cnt
        })
    fc = ee.FeatureCollection(col.map(img_to_feat))
    feats = fc.aggregate_array('date').getInfo()
    valsK = fc.aggregate_array('tmaxK').getInfo()
    counts = fc.aggregate_array('count').getInfo()
    valid_c = []
    dailyC = []
    for d, k, c in zip(feats, valsK, counts):
        c0 = 0 if c is None else int(c)
        if (k is None) or (c0 == 0) or (isinstance(k, float) and (math.isnan(k))):
            print(f"{d} TmaxC: None Pixels: {c0}")
        else:
            celsius = k - 273.15
            dailyC.append(celsius)
            valid_c.append((d, celsius, c0))
            print(f"{d} TmaxC: {celsius:.2f} Pixels: {c0}")
    if len(dailyC) < 2:
        if img_count == 0:
            print("C1")
        else:
            print("C2")
        sys.exit(0)
    maxC = max(dailyC)
    minC = min(dailyC)
    diffC = maxC - minC
    # Validate ranges (2m temps should be realistic)
    if any([math.isnan(x) for x in [maxC, minC, diffC]]) or (maxC < -100 or maxC > 60) or (minC < -100 or minC > 60):
        print("C3")
        sys.exit(0)
    print(f"MaxC: {maxC:.2f}, MinC: {minC:.2f}, DiffC: {diffC:.2f}")
    print("A" if diffC >= 30.0 else "B")
except Exception as e:
    # Any unexpected API or band errors
    print(f"Error: {str(e)[:120]}")
    print("D")
